const cfg = $('Config').first().json;
const html = $input.first().json.html;
const BASE = 'https://conhecimento.fgv.br';
const strip = s => s.replace(/<[^>]+>/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
const norm = s => (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '');
const tokenRe = /<(strong|b|h3|h4)[^>]*>([\s\S]*?)<\/\1>|<a\s+[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi;
let lastHeading = '';
const provas = [];
const gabaritos = [];
const seen = new Set();
let m;
while ((m = tokenRe.exec(html)) !== null) {
  if (m[1]) {
    const t = strip(m[2]);
    if (t && t.length > 3 && !/^[\d/.\s-]+$/.test(t)) lastHeading = t;
    continue;
  }
  let href = m[3];
  const text = strip(m[4]);
  if (!/\.pdf(\?|$)/i.test(href)) continue;
  if (href.startsWith('/')) href = BASE + href;
  if (seen.has(href)) continue;
  const fname = href.split('/').pop();
  const blob = text + ' ' + fname;
  if (/gabarito/i.test(blob) && !/recurso|interposi|comunicado/i.test(blob)) {
    seen.add(href);
    gabaritos.push({ url: href, texto: text, definitivo: /definitiv/i.test(blob) });
    continue;
  }
  const isTipoLink = /^tipo\s*\d+$/i.test(text);
  const excl = /resultado|recurso|edital|cronograma|comunicado|retifica|convoca|isencao|homologa|heteroidentifica|biopsico|titulos|demanda|indeferi|deferi|discursiva|pratica|redacao/i;
  if ((/tipo[-_ ]?\d/i.test(fname) || isTipoLink) && !excl.test(blob)) {
    seen.add(href);
    const tm = blob.match(/tipo[-_ ]?(\d+)/i);
    let cargo = isTipoLink ? lastHeading : (text || lastHeading);
    cargo = cargo.replace(/\s*tipo\s*\d+\s*$/i, '').trim();
    provas.push({ provaUrl: href, cargo, tipo: tm ? tm[1] : '1', arquivo: fname });
  }
}
if (gabaritos.length === 0) throw new Error('Nenhum gabarito encontrado na pagina do concurso ' + cfg.slug);
const defs = gabaritos.filter(g => g.definitivo);
const gabaritoUrl = (defs.length ? defs : gabaritos)[0].url;
let lista = provas;
if (cfg.filtroCargo) lista = lista.filter(p => norm(p.cargo).includes(norm(cfg.filtroCargo)));
if (cfg.maxProvas > 0) lista = lista.slice(0, cfg.maxProvas);
if (lista.length === 0) throw new Error('Nenhuma prova apos filtros (total na pagina: ' + provas.length + ')');
const anoM = cfg.slug.match(/(\d{2})(?!.*\d)/);
return [{ json: { slug: cfg.slug, ano: anoM ? 2000 + parseInt(anoM[1]) : null, gabaritoUrl, provas: lista, totalProvasPagina: provas.length } }];

const resp = $input.first().json;
if (resp.stop_reason === 'max_tokens') throw new Error('Gabarito truncado por max_tokens: aumente o limite ou divida o PDF');
const txt = (resp.content || []).filter(c => c.type === 'text').map(c => c.text).join('');
const s = txt.indexOf('{');
const e = txt.lastIndexOf('}');
if (s === -1 || e === -1) throw new Error('Resposta do gabarito sem JSON: ' + txt.slice(0, 200));
const gabaritos = JSON.parse(txt.slice(s, e + 1));
const chaves = Object.keys(gabaritos);
if (chaves.length === 0) throw new Error('Gabarito vazio');
return [{ json: { gabaritos, cargoTipos: chaves.length } }];

const meta = $('Loop Provas').first().json;
const item = $input.first();
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
return [{ json: { ...meta, b64: buf.toString('base64'), tamanhoKb: Math.round(buf.length / 1024) }, binary: item.binary }];

const resp = $input.first().json;
if (resp.stop_reason === 'max_tokens') throw new Error('Extracao truncada por max_tokens na prova ' + $('Preparar Prova').first().json.arquivo);
const txt = (resp.content || []).filter(c => c.type === 'text').map(c => c.text).join('');
const s = txt.indexOf('[');
const e = txt.lastIndexOf(']');
if (s === -1 || e === -1) throw new Error('Resposta sem array JSON: ' + txt.slice(0, 200));
const questoesRaw = JSON.parse(txt.slice(s, e + 1));
const meta = $('Preparar Prova').first().json;
const gab = $('Parsear Gabarito').first().json.gabaritos;
const norm = x => (x || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '');
const alvo = norm(meta.cargo) + 'tipo' + meta.tipo;
let respostas = {};
for (const [k, v] of Object.entries(gab)) {
  const nk = norm(k);
  if (nk === alvo) { respostas = v; break; }
  if (nk.endsWith('tipo' + meta.tipo) && (nk.includes(norm(meta.cargo)) || norm(meta.cargo).includes(nk.replace('tipo' + meta.tipo, '')))) respostas = v;
}
const provaId = 'fgv-' + meta.slug + '-' + norm(meta.cargo).slice(0, 30) + '-t' + meta.tipo;
let disciplinaAtual = null;
const questoes = questoesRaw.map(q => {
  if (q.disciplina) disciplinaAtual = q.disciplina; else q.disciplina = disciplinaAtual;
  const r = respostas[String(q.numero)] || null;
  return {
    id: provaId + '-q' + q.numero,
    numero: q.numero,
    disciplina: q.disciplina,
    assunto: q.assunto || null,
    texto_apoio: q.texto_apoio || null,
    enunciado: q.enunciado,
    alternativas: q.alternativas,
    gabarito: r === 'ANULADA' ? null : r,
    anulada: r === 'ANULADA',
    tem_imagem: !!q.tem_imagem,
    pagina_imagem: q.pagina_imagem || null,
    imagem_arquivo: q.tem_imagem && q.pagina_imagem ? provaId + '-p' + q.pagina_imagem + '.png' : null
  };
});
const semGabarito = questoes.filter(q => !q.gabarito && !q.anulada).length;
const paginas = [...new Set(questoes.filter(q => q.tem_imagem && q.pagina_imagem).map(q => q.pagina_imagem))];
const payload = {
  id: provaId,
  banca: 'FGV',
  concurso_slug: meta.slug,
  cargo: meta.cargo,
  ano: meta.ano,
  prova_tipo: meta.tipo,
  arquivo_fonte: meta.slug + '-' + meta.arquivo,
  total_questoes: questoes.length,
  questoes_sem_gabarito: semGabarito,
  questoes
};
const fileName = provaId + '.json';
return [{
  json: { provaId, fileName, totalQuestoes: questoes.length, semGabarito, temImagens: paginas.length > 0, paginas },
  binary: { data: { data: Buffer.from(JSON.stringify(payload, null, 1)).toString('base64'), mimeType: 'application/json', fileName } }
}];

const info = $('Montar JSON Final').first().json;
const prova = $('Preparar Prova').first();
return [{ json: { provaId: info.provaId, paginas: info.paginas }, binary: { data: prova.binary.data } }];

const info = $('Reanexar PDF da Prova').first().json;
const manter = new Set(info.paginas.map(Number));
const out = [];
for (const item of $input.all()) {
  for (const [key, bin] of Object.entries(item.binary || {})) {
    const m = (bin.fileName || key).match(/(\d+)\.(png|jpg|jpeg)$/i);
    if (!m) continue;
    const pagina = parseInt(m[1]);
    if (!manter.has(pagina)) continue;
    const fileName = info.provaId + '-p' + pagina + '.png';
    out.push({ json: { fileName, pagina, provaId: info.provaId }, binary: { data: { ...bin, fileName } } });
  }
}
if (out.length === 0) return [{ json: { aviso: 'Nenhuma pagina do zip casou com as paginas esperadas: ' + info.paginas.join(','), fileName: null } }];
return out;
